    "title": "Phase 0 Operating Blueprint",
    "section": "Getting started",
    "summary": "The end-to-end operating model for a tiny selective electronics reuse/refurbishment business.",
    "sourcePath": "docs/PHASE-0-OPERATING-BLUEPRINT.md",
